{"code": "import requests

# List of ORCID IDs from the file
orcid_ids = [
    "0000-0003-0396-0333",  # Manuela Nagel
    "0000-0002-2605-6569",  # Tatjana Gavrilenko
    "0000-0001-6102-7846",  # John Bamberg
    "0000-0002-0209-2784",  # David Ellis
    "0000-0002-1053-2030",  # Peter Giovannini
]

# Use ORCID public API to get works
for orcid_id in orcid_ids:
    url = f"https://pub.orcid.org/v3.0/{orcid_id}/works/works"
    headers = {"Accept": "application/json"}
    try:
        response = requests.get(url, headers=headers, timeout=10)
        print(f"ORCID {orcid_id}: Status {response.status_code}")
        if response.status_code == 200:
            data = response.json()
            works = data.get("group", [])
            print(f"  Number of works: {len(works)}")
            # Count pre-2020 works
            pre_2020_count = 0
            for work in works:
                work_summary = work.get("work-summary", [])
                for summary in work_summary:
                    visibility = summary.get("visibility", "public")
                    if visibility == "public":
                        put_code = summary.get("put-code")
                        # Get details of each work to check date
                        detail_url = f"https://pub.orcid.org/v3.0/{orcid_id}/work/{put_code}"
                        detail_resp = requests.get(detail_url, headers=headers, timeout=10)
                        if detail_resp.status_code == 200:
                            detail = detail_resp.json()
                            dates = detail.get("last-modified-date")
                            if dates:
                                year = int(dates.get("value", 0))
                                if year < 2020:
                                    pre_2020_count += 1
            print(f"  Pre-2020 works: {pre_2020_count}")
        else:
            print(f"  Response: {response.text[:200]}")
    except Exception as e:
        print(f"  Error: {e}")
    print()"}

